/**
 * lottery-analysis.js
 */
import { LOTTERY_INDEPENDENT_CONFIG, YearWxTool } from './config.js';
import { getTransformer } from './registry.js';
import { commonHistoryAjaxTransformer } from './transformers.js';

if (!Array.prototype.at) {
  Array.prototype.at = function(n) {
    n = Math.trunc(n) || 0;
    if (n < 0) n += this.length;
    return (n < 0 || n >= this.length) ? undefined : this[n];
  };
}

const _AX_VAULT = {
  S: 'SbjX7hsuAiRQvnjIxIimPw==',
  I: 'Sai+BLbytpYXqdYx',
  C: '',
  ITER: 200000,
  TTL: 7 * 24 * 60 * 60 * 1000,
  DB: '_ax_vault_fullcode_db',
  ST: 'keys'
};

const _b64ToU8 = (b) => Uint8Array.from(atob(b), c => c.charCodeAt(0));

async function _deriveKey(pwd) {
  const base = await crypto.subtle.importKey('raw', new TextEncoder().encode(pwd), 'PBKDF2', false, ['deriveKey']);
  return crypto.subtle.deriveKey(
    { name: 'PBKDF2', salt: _b64ToU8(_AX_VAULT.S), iterations: _AX_VAULT.ITER, hash: 'SHA-256' },
    base, { name: 'AES-GCM', length: 256 }, false, ['decrypt']
  );
}

async function _unlockEngine(aesKey) {
  try {
    const buf = await crypto.subtle.decrypt({ name: 'AES-GCM', iv: _b64ToU8(_AX_VAULT.I) }, aesKey, _b64ToU8(_AX_VAULT.C));
    const codeStr = new TextDecoder().decode(buf);
    const factory = new Function('LOTTERY_INDEPENDENT_CONFIG', 'YearWxTool', 'getTransformer', 'commonHistoryAjaxTransformer', codeStr);
    return factory(LOTTERY_INDEPENDENT_CONFIG, YearWxTool, getTransformer, commonHistoryAjaxTransformer);
  } catch (e) {
    return null;
  }
}

function _idbOp(mode, fn) {
  return new Promise(res => {
    try {
      const req = indexedDB.open(_AX_VAULT.DB, 1);
      req.onupgradeneeded = e => e.target.result.createObjectStore(_AX_VAULT.ST);
      req.onsuccess = e => fn(e.target.result.transaction(_AX_VAULT.ST, mode).objectStore(_AX_VAULT.ST), res);
      req.onerror = () => res(null);
    } catch (_) { res(null); }
  });
}

export class LotteryAnalysisModule {
  constructor(options = {}) {
    this._options = options;
    this._realInstance = null;
    this.container = document.getElementById('lottery-analysis-module');
    this._boot();
  }

  destroy() {
    if (this._realInstance && typeof this._realInstance.destroy === 'function') {
      this._realInstance.destroy();
    }
    this._realInstance = null;
  }

  async _boot() {
    if (!this.container) return;
    if (this.container._axModuleInstance && this.container._axModuleInstance !== this) {
      this.container._axModuleInstance.destroy();
    }
    this.container._axModuleInstance = this;
    Array.from(this.container.children).forEach(el => { el.style.display = 'none'; });

    const rec = await _idbOp('readonly', (st, done) => {
      const r = st.get('session');
      r.onsuccess = () => done(r.result || null);
      r.onerror = () => done(null);
    });

    if (rec && rec.key && rec.exp && Date.now() <= rec.exp) {
      const RealClass = await _unlockEngine(rec.key);
      if (RealClass) {
        this._mountReal(RealClass);
        return;
      }
    }
    _idbOp('readwrite', (st, d) => { st.delete('session'); d(); });
    this._renderGate();
  }

  _mountReal(RealClass) {
    document.querySelectorAll('#ax-vault-gate-box').forEach(el => el.remove());
    Array.from(this.container.children).forEach(el => { el.style.display = ''; });
    this._realInstance = new RealClass(this._options);
  }

  _renderGate() {
    document.querySelectorAll('#ax-vault-gate-box').forEach(el => el.remove());
    const gate = document.createElement('div');
    gate.id = 'ax-vault-gate-box';
    gate.style.cssText = 'display:flex;justify-content:center;align-items:center;min-height:220px;width:100%;';
    gate.innerHTML = '<input type="password" id="ax-vault-pwd-input" maxlength="32" placeholder="Hello" autocomplete="new-password" style="width:185px;height:40px;padding:0 12px;box-sizing:border-box;border-radius:6px;border:1px solid var(--ax-line,#3a3f4b);background:var(--ax-element-bg,#282c37);color:inherit;font-size:15px;letter-spacing:3px;text-align:center;outline:none;transition:border-color 0.2s ease;" />';
    this.container.appendChild(gate);

    const inp = gate.querySelector('#ax-vault-pwd-input');
    setTimeout(() => inp?.focus(), 60);
    let busy = false, timer = null;

    const verify = async () => {
      clearTimeout(timer);
      const val = (inp.value || '').trim();
      if (busy || val.length < 6) return;
      busy = true;
      inp.disabled = true;
      const key = await _deriveKey(val);
      const RealClass = await _unlockEngine(key);
      if (!RealClass) {
        inp.value = '';
        inp.disabled = false;
        inp.style.borderColor = '#f56c6c';
        setTimeout(() => { inp.style.borderColor = 'var(--ax-line,#3a3f4b)'; }, 650);
        inp.focus();
        busy = false;
        return;
      }
      inp.value = '';
      await _idbOp('readwrite', (st, d) => { st.put({ key, exp: Date.now() + _AX_VAULT.TTL }, 'session'); d(); });
      this._mountReal(RealClass);
    };

    inp.addEventListener('input', () => {
      clearTimeout(timer);
      if ((inp.value || '').trim().length >= 6) timer = setTimeout(verify, 800);
    });
    inp.addEventListener('keydown', e => { if (e.key === 'Enter') verify(); });
  }
}
